import json, os
# Check XSTest
for f in os.listdir('datasets/xstest/'):
    if f.endswith('.json') or f.endswith('.jsonl') or f.endswith('.csv'):
        fp = f'datasets/xstest/{f}'
        if f.endswith('.csv'):
            import csv
            with open(fp) as fh:
                reader = csv.DictReader(fh)
                rows = [r for i, r in enumerate(reader) if i < 3]
            print(f'{f}: keys={list(rows[0].keys()) if rows else \"empty\"}')
            if rows: print(f'  Sample: {str(rows[0])[:200]}')
        else:
            with open(fp) as fh:
                data = json.load(fh) if f.endswith('.json') else [json.loads(l) for l in fh.readlines()[:3]]
            print(f'{f}: {len(data)} items')
            if data: print(f'  Sample: {str(data[0])[:200]}')
